-- Seed/refresh the curated London restaurant set (45 venues).
-- Generated from curated-restaurants.json — do not hand-edit; regenerate from JSON.
-- Upserts by id: refreshes name/cuisine/address/coords/translations/deals, and
-- fills a cuisine-keyed image only when the row has none (never clobbers a custom one).

on conflict (id) do update set
    name           = excluded.name,
    cuisine        = excluded.cuisine,
    address        = excluded.address,
    latitude       = excluded.latitude,
    longitude      = excluded.longitude,
    name_zh_hans   = excluded.name_zh_hans,
    name_zh_hant   = excluded.name_zh_hant,
    image_url      = coalesce(public.restaurants.image_url, excluded.image_url),
    deals          = excluded.deals,
    deals_zh_hans  = excluded.deals_zh_hans,
    deals_zh_hant  = excluded.deals_zh_hant;

-- Mark deal freshness for everything that shipped with verified deals.
update public.restaurants
set last_deals_verified_at = now()
where jsonb_array_length(coalesce(deals, '[]'::jsonb)) > 0
  and last_deals_verified_at is null;
